async (page) => {
  const b = page.context().browser();
  let p = globalThis.__mp;
  if (!p) {
    const c = await b.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:3,locale:'en-US',userAgent:'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'});
    p = await c.newPage();
    await p.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
    await p.waitForTimeout(8000);
    globalThis.__mp = p;
  }
  const r = await p.evaluate(() => {
    const html = document.documentElement.outerHTML;
    const hits = (html.match(/.{0,70}Butt.{0,70}/g) || []).slice(0, 5);
    const names = Array.from(document.querySelectorAll('button')).map(x => (x.getAttribute('aria-label') || x.innerText || '').trim()).filter(Boolean);
    return {butt: hits, buttNames: names.filter(n => /butt/i.test(n) && !/button/i.test(n))};
  });
  return JSON.stringify(r);
}
